const TOOLS = [
  {
    name: 'format_value',
    description: 'Format a value as text (uppercased) or integer (numeric text).',
    inputSchema: {
      type: 'object',
      properties: {
        value: { type: 'string', description: 'The value to format.' },
        kind: { type: 'string', enum: ['text', 'integer'], description: 'How to format the value.' },
      },
      required: ['value', 'kind'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

function invalidParams(message) {
  const e = new Error(message);
  e.code = -32602;
  return e;
}

export async function callTool(name, args) {
  if (name !== 'format_value') {
    throw invalidParams(`Unknown tool: ${name}`);
  }
  if (typeof args !== 'object' || args === null) {
    throw invalidParams('Arguments must be an object');
