  // validate additional properties
  const allowed = ['value', 'kind'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw invalidParams(`Unexpected field: ${key}`);
    }
  }
  const { value, kind } = args;
  if (value === undefined) {
    throw invalidParams('Missing required field: value');
  }
  if (typeof value !== 'string') {
    throw invalidParams('value must be a string');
  }
  if (kind === undefined) {
    throw invalidParams('Missing required field: kind');
  }
  if (kind !== 'text' && kind !== 'integer') {
    throw invalidParams('kind must be one of: text, integer');
