    text = value.toUpperCase();
  } else {
    if (!/^[+-]?\d+$/.test(value)) {
      throw invalidParams(`Malformed integer: ${value}`);
    }
    text = parseInt(value, 10).toString();
  }
  return { content: [{ type: 'text', text }] };
}
